    19→function normalizeContent(content: unknown): Array<Record<string, unknown>> {
    20→  if (!Array.isArray(content)) {
    21→    return [];
    22→  }
    23→  return content.filter(Boolean) as Array<Record<string, unknown>>;
    24→}
    25→
    26→function coerceArgs(value: unknown): unknown {
    27→  if (typeof value !== "string") {
    28→    return value;
    29→  }
    30→  const trimmed = value.trim();
    31→  if (!trimmed) {
    32→    return value;
    33→  }
    34→  if (!trimmed.startsWith("{") && !trimmed.startsWith("[")) {
    35→    return value;
    36→  }
    37→  try {
    38→    return JSON.parse(trimmed);
    39→  } catch {
    40→    return value;
    41→  }
    42→}
    43→
    44→function extractToolText(item: Record<string, unknown>): string | undefined {
    45→  if (typeof item.text === "string") {
    46→    return item.text;
    47→  }
    48→  if (typeof item.content === "string") {
    49→    return item.content;
