    51→  if (Array.isArray(item.content)) {
    52→    const parts = item.content.flatMap((entry) => {
    53→      if (!entry || typeof entry !== "object") {
    54→        return [];
    55→      }
    56→      const text = (entry as { text?: unknown }).text;
    57→      return typeof text === "string" ? [text] : [];
    58→    });
    59→    if (parts.length > 0) {
    60→      return parts.join("\n");
    61→    }
    62→  }
    63→  return undefined;
    64→}
    65→
    66→export function extractToolPreview(
    67→  outputText: string | undefined,
