    81→    (typeof item.toolCallId === "string" && item.toolCallId.trim()) ||
    82→    (typeof item.tool_call_id === "string" && item.tool_call_id.trim()) ||
    83→    (typeof item.callId === "string" && item.callId.trim()) ||
    84→    (typeof message.toolCallId === "string" && message.toolCallId.trim()) ||
    85→    (typeof message.tool_call_id === "string" && message.tool_call_id.trim()) ||
