    97→
    98→function serializeToolInput(args: unknown): string | undefined {
    99→  if (args === undefined || args === null) {
   100→    return undefined;
   101→  }
   102→  if (typeof args === "string") {
   103→    return args;
   104→  }
   105→  try {
   106→    return JSON.stringify(args, null, 2);
   107→  } catch {
   108→    if (typeof args === "number" || typeof args === "boolean" || typeof args === "bigint") {
   109→      return String(args);
   110→    }
   111→    if (typeof args === "symbol") {
   112→      return args.description ? `Symbol(${args.description})` : "Symbol()";
   113→    }
   114→    return Object.prototype.toString.call(args);
