   116→}
   117→
   118→function formatPayloadForSidebar(
   119→  text: string | undefined,
   120→  language: "json" | "text" = "text",
   121→): string {
   122→  if (!text?.trim()) {
   123→    return "";
   124→  }
   125→  if (language === "json") {
   126→    return `\`\`\`json
   127→${text}
   128→\`\`\``;
   129→  }
   130→  const formatted = formatToolOutputForSidebar(text);
   131→  if (formatted.includes("```")) {
   132→    return formatted;
   133→  }
   134→  return `\`\`\`text
   135→${text}
   136→\`\`\``;
   137→}
   138→
   139→function findLatestCard(cards: ToolCard[], id: string, name: string): ToolCard | undefined {
   140→  for (let i = cards.length - 1; i >= 0; i--) {
   141→    const card = cards[i];
   142→    if (!card) {
   143→      continue;
   144→    }
   145→    if (card.id === id || (card.name === name && !card.outputText)) {
   146→      return card;
   147→    }
   148→  }
   149→  return undefined;
   150→}
   151→
   152→export function extractToolCards(message: unknown, prefix = "tool"): ToolCard[] {
   153→  const m = message as Record<string, unknown>;
   154→  const content = normalizeContent(m.content);
   155→  const cards: ToolCard[] = [];
   156→
   157→  for (let index = 0; index < content.length; index++) {
   158→    const item = content[index] ?? {};
   159→    const kind = (typeof item.type === "string" ? item.type : "").toLowerCase();
   160→    const isToolCall =
   161→      ["toolcall", "tool_call", "tooluse", "tool_use"].includes(kind) ||
   162→      (typeof item.name === "string" &&
   163→        (item.arguments != null || item.args != null || item.input != null));
   164→    if (isToolCall) {
   165→      const args = coerceArgs(item.arguments ?? item.args ?? item.input);
   166→      cards.push({
   167→        id: resolveToolCardId(item, m, index, prefix),
   168→        name: (item.name as string) ?? "tool",
