   170→        inputText: serializeToolInput(args),
   171→      });
   172→      continue;
   173→    }
   174→
   175→    if (kind === "toolresult" || kind === "tool_result") {
   176→      const name = typeof item.name === "string" ? item.name : "tool";
   177→      const cardId = resolveToolCardId(item, m, index, prefix);
   178→      const existing = findLatestCard(cards, cardId, name);
   179→      const text = extractToolText(item);
   180→      const preview = extractToolPreview(text, name);
   181→      if (existing) {
   182→        existing.outputText = text;
   183→        existing.preview = preview;
   184→        continue;
   185→      }
   186→      cards.push({
   187→        id: cardId,
   188→        name,
   189→        outputText: text,
   190→        preview,
   191→      });
   192→    }
   193→  }
   194→
   195→  const role = typeof m.role === "string" ? m.role.toLowerCase() : "";
   196→  const isStandaloneToolMessage =
   197→    isToolResultMessage(message) ||
   198→    role === "tool" ||
   199→    role === "function" ||
   200→    typeof m.toolName === "string" ||
   201→    typeof m.tool_name === "string";
   202→
   203→  if (isStandaloneToolMessage && cards.length === 0) {
   204→    const name =
   205→      (typeof m.toolName === "string" && m.toolName) ||
   206→      (typeof m.tool_name === "string" && m.tool_name) ||
   207→      "tool";
   208→    const text = extractTextCached(message) ?? undefined;
   209→    cards.push({
