   282→    allowExternalEmbedUrls?: boolean;
   283→  },
   284→) {
   285→  if (!preview) {
   286→    return nothing;
   287→  }
   288→  if (preview.kind !== "canvas" || surface === "chat_tool") {
   289→    return nothing;
   290→  }
   291→  if (preview.surface !== "assistant_message") {
   292→    return nothing;
   293→  }
