   323→    kind: "markdown",
   324→    content: value,
   325→    ...(options?.rawText ? { rawText: options.rawText } : {}),
   326→  };
   327→}
   328→
   329→export function buildPreviewSidebarContent(
   330→  preview: ToolPreview,
   331→  rawText?: string | null,
   332→): SidebarContent | null {
   333→  if (preview.kind !== "canvas" || preview.render !== "url" || !preview.viewId || !preview.url) {
   334→    return null;
   335→  }
   336→  return {
   337→    kind: "canvas",
   338→    docId: preview.viewId,
   339→    entryUrl: preview.url,
   340→    ...(preview.title ? { title: preview.title } : {}),
   341→    ...(preview.preferredHeight ? { preferredHeight: preview.preferredHeight } : {}),
   342→    ...(rawText ? { rawText } : {}),
   343→  };
   344→}
   345→
   346→export function renderRawOutputToggle(text: string) {
   347→  return html`
   348→    <div class="chat-tool-card__raw">
   349→      <button
   350→        class="chat-tool-card__raw-toggle"
   351→        type="button"
   352→        aria-expanded="false"
   353→        @click=${handleRawDetailsToggle}
   354→      >
   355→        <span>Raw details</span>
   356→        <span class="chat-tool-card__raw-toggle-icon">${icons.chevronDown}</span>
   357→      </button>
   358→      <div class="chat-tool-card__raw-body" hidden>
   359→        ${renderToolDataBlock({
   360→          label: "Tool output",
   361→          text,
   362→          expanded: true,
   363→        })}
   364→      </div>
   365→    </div>
   366→  `;
   367→}
   368→
   369→function renderToolDataBlock(params: {
   370→  label: string;
   371→  text: string;
   372→  expanded: boolean;
   373→  empty?: boolean;
   374→}) {
   375→  const { label, text, expanded, empty } = params;
