   556→      role=${canClick ? "button" : nothing}
   557→      tabindex=${canClick ? "0" : nothing}
   558→      @keydown=${canClick
   559→        ? (e: KeyboardEvent) => {
   560→            if (e.key !== "Enter" && e.key !== " ") {
   561→              return;
