    22→function appendCanvasBlockToAssistantMessage(
    23→  message: unknown,
    24→  preview: Extract<NonNullable<ToolCard["preview"]>, { kind: "canvas" }>,
    25→  rawText: string | null,
    26→) {
    27→  const raw = message as Record<string, unknown>;
    28→  const existingContent = Array.isArray(raw.content)
    29→    ? [...raw.content]
    30→    : typeof raw.content === "string"
    31→      ? [{ type: "text", text: raw.content }]
    32→      : typeof raw.text === "string"
    33→        ? [{ type: "text", text: raw.text }]
    34→        : [];
    35→  const alreadyHasArtifact = existingContent.some((block) => {
    36→    if (!block || typeof block !== "object") {
    37→      return false;
    38→    }
    39→    const typed = block as {
    40→      type?: unknown;
    41→      preview?: { kind?: unknown; viewId?: unknown; url?: unknown };
    42→    };
    43→    return (
    44→      typed.type === "canvas" &&
    45→      typed.preview?.kind === "canvas" &&
    46→      ((preview.viewId && typed.preview.viewId === preview.viewId) ||
    47→        (preview.url && typed.preview.url === preview.url))
    48→    );
    49→  });
    50→  if (alreadyHasArtifact) {
    51→    return message;
    52→  }
    53→  return {
    54→    ...raw,
    55→    content: [
    56→      ...existingContent,
    57→      {
    58→        type: "canvas",
    59→        preview,
    60→        ...(rawText ? { rawText } : {}),
    61→      },
    62→    ],
    63→  };
    64→}
