   127→const managedImageBlobUrlMissCache = new Map<string, number>();
   128→const MANAGED_IMAGE_BLOB_URL_MISS_RETRY_MS = 5_000;
   129→
   130→function appendImageBlock(images: ImageBlock[], block: ImageBlock) {
   131→  if (!images.some((entry) => entry.url === block.url && entry.alt === block.alt)) {
   132→    images.push(block);
   133→  }
   134→}
   135→
   136→function buildBase64ImageUrl(params: { data: string; mediaType?: string }): string {
   137→  return params.data.startsWith("data:")
   138→    ? params.data
   139→    : `data:${params.mediaType ?? "image/png"};base64,${params.data}`;
   140→}
   141→
   142→function getFileExtension(url: string): string | undefined {
   143→  const source = (() => {
   144→    try {
   145→      const trimmed = url.trim();
   146→      if (/^https?:\/\//i.test(trimmed)) {
   147→        return new URL(trimmed).pathname;
   148→      }
   149→    } catch {
   150→      // Fall back to the raw path when URL parsing fails.
   151→    }
   152→    return url;
   153→  })();
   154→  const fileName = source.split(/[\\/]/).pop() ?? source;
   155→  const match = /\.([a-zA-Z0-9]+)$/.exec(fileName);
   156→  return match?.[1]?.toLowerCase();
   157→}
   158→
   159→function isImageTranscriptMediaPath(path: string, mediaType: unknown): boolean {
   160→  if (typeof mediaType === "string" && mediaType.trim()) {
   161→    const normalized = mediaType.trim().toLowerCase();
   162→    if (normalized.startsWith("image/")) {
   163→      return true;
   164→    }
   165→    if (normalized !== "application/octet-stream") {
   166→      return false;
   167→    }
   168→  }
   169→  const ext = getFileExtension(path);
   170→  return (
   171→    ext !== undefined &&
   172→    ["png", "jpg", "jpeg", "gif", "webp", "bmp", "svg", "heic", "heif", "avif"].includes(ext)
   173→  );
   174→}
   175→
   176→function isAudioTranscriptMediaPath(path: string, mediaType: unknown): boolean {
   177→  if (typeof mediaType === "string" && mediaType.trim().toLowerCase().startsWith("audio/")) {
   178→    return true;
   179→  }
   180→  const ext = getFileExtension(path);
   181→  return (
   182→    ext !== undefined && ["aac", "flac", "m4a", "mp3", "oga", "ogg", "opus", "wav"].includes(ext)
   183→  );
   184→}
   185→
   186→function isVideoTranscriptMediaPath(path: string, mediaType: unknown): boolean {
   187→  if (typeof mediaType === "string" && mediaType.trim().toLowerCase().startsWith("video/")) {
   188→    return true;
   189→  }
   190→  const ext = getFileExtension(path);
   191→  return ext !== undefined && ["m4v", "mov", "mp4", "webm"].includes(ext);
   192→}
   193→
   194→function labelForMediaPath(mediaPath: string): string {
   195→  const trimmed = mediaPath.trim();
   196→  try {
   197→    if (/^https?:\/\//i.test(trimmed)) {
   198→      const parsed = new URL(trimmed);
   199→      return parsed.pathname.split("/").pop()?.trim() || parsed.hostname || trimmed;
   200→    }
   201→  } catch {}
   202→  return trimmed.split(/[\\/]/).pop()?.trim() || trimmed;
   203→}
   204→
   205→function extractTranscriptMediaEntries(message: unknown): Array<{
   206→  path: string;
   207→  mediaType: unknown;
   208→}> {
   209→  const m = message as Record<string, unknown>;
   210→  const transcriptMediaPaths = Array.isArray(m.MediaPaths)
   211→    ? m.MediaPaths.filter((value): value is string => typeof value === "string")
   212→    : typeof m.MediaPath === "string"
   213→      ? [m.MediaPath]
   214→      : [];
   215→  const transcriptMediaTypes = Array.isArray(m.MediaTypes)
   216→    ? m.MediaTypes
   217→    : typeof m.MediaType === "string"
   218→      ? [m.MediaType]
   219→      : [];
   220→  return transcriptMediaPaths.map((mediaPath, index) => ({
   221→    path: mediaPath,
   222→    mediaType: transcriptMediaTypes[index],
   223→  }));
   224→}
   225→
   226→function extractImages(message: unknown): ImageBlock[] {
   227→  const m = message as Record<string, unknown>;
   228→  const content = m.content;
   229→  const images: ImageBlock[] = [];
   230→
   231→  if (Array.isArray(content)) {
   232→    for (const block of content) {
   233→      if (typeof block !== "object" || block === null) {
   234→        continue;
   235→      }
   236→      const b = block as Record<string, unknown>;
   237→
   238→      if (b.type === "image") {
   239→        // Handle source object format (from sendChatMessage)
   240→        const source = b.source as Record<string, unknown> | undefined;
   241→        const imageMeta = {
   242→          alt: typeof b.alt === "string" ? b.alt : undefined,
   243→          openUrl: typeof b.openUrl === "string" ? b.openUrl : undefined,
   244→          width: typeof b.width === "number" ? b.width : undefined,
   245→          height: typeof b.height === "number" ? b.height : undefined,
   246→        };
   247→        if (source?.type === "base64" && typeof source.data === "string") {
   248→          appendImageBlock(images, {
   249→            url: buildBase64ImageUrl({
   250→              data: source.data,
   251→              mediaType: typeof source.media_type === "string" ? source.media_type : undefined,
   252→            }),
   253→            ...imageMeta,
   254→          });
   255→        } else if (typeof b.url === "string") {
   256→          appendImageBlock(images, { url: b.url, ...imageMeta });
   257→        }
   258→      } else if (b.type === "image_url") {
   259→        // OpenAI format
   260→        const imageUrl = b.image_url as Record<string, unknown> | undefined;
   261→        if (typeof imageUrl?.url === "string") {
   262→          appendImageBlock(images, { url: imageUrl.url });
   263→        }
   264→      } else if (b.type === "input_image") {
   265→        const imageUrl = b.image_url;
   266→        if (typeof imageUrl === "string") {
   267→          appendImageBlock(images, { url: imageUrl });
   268→        } else if (imageUrl && typeof imageUrl === "object") {
   269→          const url = (imageUrl as Record<string, unknown>).url;
   270→          if (typeof url === "string") {
   271→            appendImageBlock(images, { url });
   272→          }
   273→        }
   274→        const source = b.source as Record<string, unknown> | undefined;
   275→        if (typeof source?.url === "string") {
   276→          appendImageBlock(images, { url: source.url });
   277→        } else if (typeof source?.data === "string") {
   278→          appendImageBlock(images, {
   279→            url: buildBase64ImageUrl({
   280→              data: source.data,
   281→              mediaType: typeof source.media_type === "string" ? source.media_type : undefined,
   282→            }),
   283→          });
   284→        }
   285→      }
   286→    }
   287→  }
   288→
   289→  for (const { path: mediaPath, mediaType } of extractTranscriptMediaEntries(message)) {
   290→    if (!isImageTranscriptMediaPath(mediaPath, mediaType)) {
   291→      continue;
   292→    }
   293→    appendImageBlock(images, { url: mediaPath });
   294→  }
   295→
   296→  return images;
   297→}
   298→
   299→function extractTranscriptAttachments(message: unknown): AttachmentItem[] {
   300→  const attachments: AttachmentItem[] = [];
   301→  for (const { path: mediaPath, mediaType } of extractTranscriptMediaEntries(message)) {
   302→    if (isImageTranscriptMediaPath(mediaPath, mediaType)) {
   303→      continue;
   304→    }
   305→    const kind = isAudioTranscriptMediaPath(mediaPath, mediaType)
   306→      ? "audio"
   307→      : isVideoTranscriptMediaPath(mediaPath, mediaType)
   308→        ? "video"
   309→        : "document";
   310→    attachments.push({
   311→      type: "attachment",
   312→      attachment: {
   313→        url: mediaPath,
   314→        kind,
   315→        label: labelForMediaPath(mediaPath),
   316→        ...(typeof mediaType === "string" ? { mimeType: mediaType } : {}),
   317→      },
   318→    });
   319→  }
   320→  return attachments;
   321→}
