   479→
   480→// ── Per-message metadata (tokens, cost, model, context %) ──
   481→
   482→type GroupMeta = {
   483→  input: number;
   484→  output: number;
   485→  cacheRead: number;
   486→  cacheWrite: number;
   487→  cost: number;
   488→  model: string | null;
   489→  contextPercent: number | null;
   490→};
   491→
   492→function extractGroupMeta(group: MessageGroup, contextWindow: number | null): GroupMeta | null {
   493→  let input = 0;
   494→  let output = 0;
   495→  let cacheRead = 0;
   496→  let cacheWrite = 0;
   497→  let cost = 0;
   498→  let model: string | null = null;
   499→  let hasUsage = false;
   500→  let maxPromptTokens = 0;
   501→
   502→  for (const { message } of group.messages) {
   503→    const m = message as Record<string, unknown>;
   504→    if (m.role !== "assistant") {
   505→      continue;
   506→    }
   507→    const usage = m.usage as Record<string, number> | undefined;
   508→    if (usage) {
   509→      hasUsage = true;
   510→      const callInput = usage.input ?? usage.inputTokens ?? 0;
   511→      const callOutput = usage.output ?? usage.outputTokens ?? 0;
   512→      const callCacheRead = usage.cacheRead ?? usage.cache_read_input_tokens ?? 0;
   513→      const callCacheWrite = usage.cacheWrite ?? usage.cache_creation_input_tokens ?? 0;
   514→      input += callInput;
   515→      output += callOutput;
   516→      cacheRead += callCacheRead;
   517→      cacheWrite += callCacheWrite;
   518→      maxPromptTokens = Math.max(maxPromptTokens, callInput + callCacheRead + callCacheWrite);
   519→    }
   520→    const c = m.cost as Record<string, number> | undefined;
   521→    if (c?.total) {
   522→      cost += c.total;
   523→    }
   524→    if (typeof m.model === "string" && m.model !== "gateway-injected") {
   525→      model = m.model;
   526→    }
   527→  }
   528→
   529→  if (!hasUsage && !model) {
   530→    return null;
   531→  }
   532→
   533→  const contextPercent =
   534→    contextWindow && maxPromptTokens > 0
   535→      ? Math.min(Math.round((maxPromptTokens / contextWindow) * 100), 100)
   536→      : null;
   537→
   538→  return { input, output, cacheRead, cacheWrite, cost, model, contextPercent };
   539→}
   540→
   541→/** Compact token count formatter (e.g. 128000 → "128k"). */
   542→function fmtTokens(n: number): string {
   543→  if (n >= 1_000_000) {
   544→    return `${(n / 1_000_000).toFixed(1).replace(/\.0$/, "")}M`;
   545→  }
   546→  if (n >= 1_000) {
   547→    return `${(n / 1_000).toFixed(1).replace(/\.0$/, "")}k`;
   548→  }
   549→  return String(n);
   550→}
   551→
   552→function renderMessageMeta(meta: GroupMeta | null) {
   553→  if (!meta) {
   554→    return nothing;
   555→  }
   556→
   557→  const parts: Array<ReturnType<typeof html>> = [];
   558→
   559→  // Token counts: ↑input ↓output
   560→  if (meta.input) {
   561→    parts.push(html`<span class="msg-meta__tokens">↑${fmtTokens(meta.input)}</span>`);
   562→  }
   563→  if (meta.output) {
   564→    parts.push(html`<span class="msg-meta__tokens">↓${fmtTokens(meta.output)}</span>`);
   565→  }
   566→
   567→  // Cache: R/W
   568→  if (meta.cacheRead) {
   569→    parts.push(html`<span class="msg-meta__cache">R${fmtTokens(meta.cacheRead)}</span>`);
   570→  }
   571→  if (meta.cacheWrite) {
   572→    parts.push(html`<span class="msg-meta__cache">W${fmtTokens(meta.cacheWrite)}</span>`);
   573→  }
   574→
   575→  // Cost
   576→  if (meta.cost > 0) {
   577→    parts.push(html`<span class="msg-meta__cost">$${meta.cost.toFixed(4)}</span>`);
   578→  }
   579→
   580→  // Context %
   581→  if (meta.contextPercent !== null) {
   582→    const pct = meta.contextPercent;
   583→    const cls =
   584→      pct >= 90
   585→        ? "msg-meta__ctx msg-meta__ctx--danger"
   586→        : pct >= 75
   587→          ? "msg-meta__ctx msg-meta__ctx--warn"
   588→          : "msg-meta__ctx";
   589→    parts.push(html`<span class="${cls}">${pct}% ctx</span>`);
   590→  }
   591→
   592→  // Model
   593→  if (meta.model) {
   594→    // Shorten model name: strip provider prefix if present (e.g. "anthropic/claude-3.5-sonnet" → "claude-3.5-sonnet")
   595→    const shortModel = meta.model.includes("/") ? meta.model.split("/").pop()! : meta.model;
   596→    parts.push(html`<span class="msg-meta__model">${shortModel}</span>`);
   597→  }
   598→
   599→  if (parts.length === 0) {
   600→    return nothing;
   601→  }
   602→
   603→  return html`
   604→    <details class="msg-meta">
   605→      <summary class="msg-meta__summary" title="Show message context details">
   606→        <span class="msg-meta__summary-icon" aria-hidden="true">${icons.chevronRight}</span>
   607→        <span>Context</span>
   608→      </summary>
   609→      <span class="msg-meta__details">${parts}</span>
   610→    </details>
   611→  `;
   612→}
   613→
   614→const SKIP_DELETE_CONFIRM_KEY = "openclaw:skipDeleteConfirm";
   615→
   616→type DeleteConfirmSide = "left" | "right";
   617→
   618→const deleteConfirmDismissers = new WeakMap<Element, () => void>();
   619→
   620→function shouldSkipDeleteConfirm(): boolean {
   621→  try {
   622→    return getSafeLocalStorage()?.getItem(SKIP_DELETE_CONFIRM_KEY) === "1";
   623→  } catch {
   624→    return false;
   625→  }
   626→}
   627→
   628→function dismissDeleteConfirm(element: Element) {
   629→  const dismiss = deleteConfirmDismissers.get(element);
   630→  if (dismiss) {
   631→    dismiss();
   632→    return;
   633→  }
   634→  element.remove();
   635→}
   636→
   637→function renderDeleteButton(onDelete: () => void, side: DeleteConfirmSide) {
   638→  return html`
   639→    <span class="chat-delete-wrap">
   640→      <button
   641→        class="chat-group-delete"
   642→        title="Delete"
   643→        aria-label="Delete message"
   644→        @click=${(e: Event) => {
   645→          if (shouldSkipDeleteConfirm()) {
   646→            onDelete();
   647→            return;
   648→          }
   649→          const btn = e.currentTarget as HTMLElement;
   650→          const wrap = btn.closest(".chat-delete-wrap") as HTMLElement;
   651→          const existing = wrap?.querySelector(".chat-delete-confirm");
   652→          if (existing) {
   653→            dismissDeleteConfirm(existing);
   654→            return;
   655→          }
   656→          const popover = document.createElement("div");
   657→          popover.className = `chat-delete-confirm chat-delete-confirm--${side}`;
   658→          popover.innerHTML = `
   659→            <p class="chat-delete-confirm__text">Delete this message?</p>
   660→            <label class="chat-delete-confirm__remember">
   661→              <input type="checkbox" class="chat-delete-confirm__check" />
   662→              <span>Don't ask again</span>
   663→            </label>
   664→            <div class="chat-delete-confirm__actions">
   665→              <button class="chat-delete-confirm__cancel" type="button">Cancel</button>
   666→              <button class="chat-delete-confirm__yes" type="button">Delete</button>
   667→            </div>
   668→          `;
   669→          wrap.appendChild(popover);
   670→
   671→          const cancel = popover.querySelector(".chat-delete-confirm__cancel")!;
   672→          const yes = popover.querySelector(".chat-delete-confirm__yes")!;
   673→          const check = popover.querySelector(".chat-delete-confirm__check") as HTMLInputElement;
   674→
   675→          let dismissed = false;
   676→          function dismissPopover() {
   677→            if (dismissed) {
   678→              return;
   679→            }
   680→            dismissed = true;
   681→            document.removeEventListener("click", closeOnOutside, true);
   682→            deleteConfirmDismissers.delete(popover);
   683→            popover.remove();
   684→          }
   685→          function closeOnOutside(evt: MouseEvent) {
   686→            const target = evt.target;
   687→            if (target instanceof Node && !popover.contains(target) && !btn.contains(target)) {
   688→              dismissPopover();
   689→            }
   690→          }
   691→
   692→          deleteConfirmDismissers.set(popover, dismissPopover);
   693→
   694→          cancel.addEventListener("click", dismissPopover);
   695→          yes.addEventListener("click", () => {
   696→            if (check.checked) {
   697→              try {
   698→                getSafeLocalStorage()?.setItem(SKIP_DELETE_CONFIRM_KEY, "1");
   699→              } catch {}
   700→            }
   701→            dismissPopover();
   702→            onDelete();
   703→          });
   704→
   705→          requestAnimationFrame(() => {
   706→            if (!dismissed && popover.isConnected) {
   707→              document.addEventListener("click", closeOnOutside, true);
   708→            }
   709→          });
   710→        }}
   711→      >
   712→        ${icons.trash ?? icons.x}
   713→      </button>
   714→    </span>
   715→  `;
   716→}
   717→
   718→function resolveRenderableMessageImages(
   719→  images: ImageBlock[],
   720→  opts?: ImageRenderOptions,
   721→): RenderableImageBlock[] {
   722→  return images.flatMap((img) => {
   723→    const isLocalImage = isLocalAssistantAttachmentSource(img.url);
   724→    const canProxyLocalImage =
   725→      isLocalImage && isLocalAttachmentPreviewAllowed(img.url, opts?.localMediaPreviewRoots ?? []);
   726→    if (isLocalImage && !canProxyLocalImage) {
   727→      return [];
   728→    }
   729→    const availability = canProxyLocalImage
   730→      ? resolveAssistantAttachmentAvailability(
   731→          img.url,
   732→          opts?.localMediaPreviewRoots ?? [],
   733→          opts?.basePath,
   734→          opts?.authToken,
   735→          opts?.onRequestUpdate,
   736→        )
   737→      : { status: "available" as const };
   738→    if (availability.status !== "available") {
   739→      return [];
   740→    }
   741→    const displayUrl = canProxyLocalImage
   742→      ? buildAssistantAttachmentUrl(img.url, opts?.basePath, availability.mediaTicket)
   743→      : img.url;
   744→    return [{ ...img, displayUrl }];
   745→  });
   746→}
   747→
   748→function renderMessageImages(images: RenderableImageBlock[], opts?: ImageRenderOptions) {
   749→  if (images.length === 0) {
   750→    return nothing;
   751→  }
   752→
   753→  const openImage = (url: string) => {
   754→    openExternalUrlSafe(url, { allowDataImage: true });
   755→  };
   756→
   757→  const renderImageElement = (img: RenderableImageBlock, previewUrl: string) => html`
   758→    <img
   759→      src=${previewUrl}
   760→      alt=${img.alt ?? "Attached image"}
   761→      class="chat-message-image"
   762→      width=${img.width ?? nothing}
   763→      height=${img.height ?? nothing}
   764→      @click=${() => openImage(previewUrl)}
   765→    />
   766→  `;
   767→
   768→  const renderImage = (img: RenderableImageBlock) => {
   769→    if (!isManagedOutgoingImageSource(img.displayUrl)) {
   770→      return renderImageElement(img, img.displayUrl);
   771→    }
   772→    const preview = resolveManagedOutgoingImageBlobUrl(img.displayUrl, opts).then((previewUrl) => {
   773→      if (!previewUrl) {
   774→        return nothing;
   775→      }
   776→      return renderImageElement(img, previewUrl);
   777→    });
   778→    return until(preview, nothing);
   779→  };
   780→
   781→  return html` <div class="chat-message-images">${images.map((img) => renderImage(img))}</div> `;
   782→}
