  1256→        if (!attachmentUrl) {
  1257→          return renderAssistantAttachmentStatusCard({
  1258→            kind: "document",
  1259→            label: attachment.label,
  1260→            badge: availability.status === "checking" ? "Checking..." : "Unavailable",
  1261→            reason: availability.status === "unavailable" ? availability.reason : undefined,
  1262→          });
  1263→        }
  1264→        return html`
  1265→          <div class="chat-assistant-attachment-card">
