    40→function snapBorderRadius(value: number): BorderRadiusStop {
    41→  let best: BorderRadiusStop = BORDER_RADIUS_STOPS[0];
    42→  let bestDist = Math.abs(value - best);
    43→  for (const stop of BORDER_RADIUS_STOPS) {
    44→    const dist = Math.abs(value - stop);
    45→    if (dist < bestDist) {
    46→      best = stop;
    47→      bestDist = dist;
    48→    }
    49→  }
    50→  return best;
    51→}
