import { html, nothing } from "lit";

export type DebugFrame = { direction: "out" | "in"; ts: number; data: unknown };

export function renderDebugModal(params: {
  open: boolean;
  frames: DebugFrame[];
  onClose: () => void;
}) {
  if (!params.open) {
    return nothing;
  }

  const frames = params.frames;
  const jsonContent = JSON.stringify(frames, null, 2);

  return html`
    <openclaw-modal-dialog label="Debug - Raw Frames" @modal-cancel=${params.onClose}>
      <div
        style="
          background: var(--surface, #1e1e2e);
          border: 1px solid var(--border, #333);
          border-radius: var(--radius-lg, 12px);
          display: flex;
          flex-direction: column;
          max-height: calc(100dvh - 96px);
          overflow: hidden;
        "
      >
        <div
          style="
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 12px 16px;
            border-bottom: 1px solid var(--border, #333);
          "
        >
          <span style="font-weight: 600; font-size: 14px;">
            Debug (${frames.length} frames)
          </span>
          <button
            class="btn btn--sm"
            @click=${params.onClose}
            style="font-size: 12px;"
          >
            Close
          </button>
        </div>
        <div style="overflow: auto; padding: 12px 16px; flex: 1;">
          ${frames.length === 0
            ? html`<p style="opacity: 0.6; margin: 0;">No frames captured yet. Send a message first.</p>`
            : html`<pre
                style="
                  margin: 0;
                  font-size: 12px;
                  line-height: 1.5;
                  white-space: pre-wrap;
                  word-break: break-all;
                  font-family: var(--font-mono, monospace);
                "
              >${jsonContent}</pre>`}
        </div>
      </div>
    </openclaw-modal-dialog>
  `;
}

