onOpenSessionCheckpoints: () => {
  state.sessionsExpandedCheckpointKey = state.sessionKey;
  state.setTab("sessions" as import("./navigation.ts").Tab);
  void loadSessions(state, {
    activeMinutes: 0,
    limit: 0,
    includeGlobal: true,
    includeUnknown: true,
  });
