import { html, nothing } from "lit";
import type { GatewayBrowserClient } from "../gateway.ts";

export type DebugFrame = { direction: "out" | "in"; ts: number; data: unknown };

export type DebugModalState = {
  open: boolean;
  loading: boolean;
  events: unknown[];
  error: string | null;
};

export async function loadDebugCaptureEvents(client: GatewayBrowserClient | null): Promise<{
  events: unknown[];
  error: string | null;
}> {
  if (!client) {
    return { events: [], error: "Gateway not connected" };
  }
  try {
    const result = (await client.request("debug.capture.recent", { limit: 100 })) as {
      enabled: boolean;
      events?: unknown[];
    };
    if (!result.enabled) {
      return { events: [], error: "Debug proxy not enabled. Set OPENCLAW_DEBUG_PROXY_ENABLED=1" };
    }
    return { events: result.events ?? [], error: null };
  } catch (err) {
    return { events: [], error: err instanceof Error ? err.message : String(err) };
  }
}

export function renderDebugModal(params: {
  open: boolean;
  frames: DebugFrame[];
  captureEvents: unknown[];
  captureLoading: boolean;
  captureError: string | null;
  onClose: () => void;
}) {
  if (!params.open) {
    return nothing;
  }

  const events = params.captureEvents;
  const jsonContent = events.length > 0 ? JSON.stringify(events, null, 2) : "";

  return html`
    <openclaw-modal-dialog label="Debug - LLM Raw Payloads" @modal-cancel=${params.onClose}>
      <div
        style="
          background: #ffffff;
          color: #1a1a1a;
          border: 1px solid #e0e0e0;
          border-radius: 12px;
          display: flex;
          flex-direction: column;
          max-height: calc(100dvh - 96px);
          width: min(900px, calc(100vw - 48px));
          overflow: hidden;
          box-shadow: 0 8px 32px rgba(0,0,0,0.12);
        "
      >
        <div
          style="
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 12px 16px;
            border-bottom: 1px solid #e0e0e0;
          "
        >
          <span style="font-weight: 600; font-size: 14px; color: #1a1a1a;">
            LLM Request/Response (${events.length} events)
          </span>
          <button
            class="btn btn--sm"
            @click=${params.onClose}
            style="font-size: 12px;"
          >
            Close
          </button>
        </div>
        <div style="overflow: auto; padding: 12px 16px; flex: 1; background: #fafafa;">
          ${params.captureLoading
            ? html`<p style="margin: 0; color: #666;">Loading...</p>`
            : params.captureError
              ? html`<p style="margin: 0; color: #d32f2f;">${params.captureError}</p>`
              : events.length === 0
                ? html`<p style="margin: 0; color: #666;">No LLM requests captured. Send a message first.</p>`
                : html`<pre
                    style="
                      margin: 0;
                      font-size: 12px;
                      line-height: 1.5;
                      white-space: pre-wrap;
                      word-break: break-all;
                      font-family: 'SF Mono', 'Fira Code', monospace;
                      color: #1a1a1a;
                    "
                  >${jsonContent}</pre>`}
        </div>
      </div>
    </openclaw-modal-dialog>
  `;
}

