export function renderDebugModal(params: {
  open: boolean;
  frames: DebugFrame[];
  captureEvents: unknown[];
  captureLoading: boolean;
  captureError: string | null;
  onClose: () => void;
}) {
  if (!params.open) {
    return nothing;
  }

  const events = (params.captureEvents as CaptureEvent[])
    .filter((e) => e.body != null)
    .sort((a, b) => {
      // Request first, then Response; within same kind, older first
      const aReq = a.kind === "request" ? 0 : 1;
      const bReq = b.kind === "request" ? 0 : 1;
      if (aReq !== bReq) return aReq - bReq;
      return 0;
    });

  return html`
    <openclaw-modal-dialog label="Debug - LLM Raw Payloads" @modal-cancel=${params.onClose}>
      <div
        style="
          background: #ffffff;
          color: #1a1a1a;
          border: 1px solid #e0e0e0;
          border-radius: 12px;
          display: flex;
          flex-direction: column;
          max-height: calc(100dvh - 96px);
          width: min(900px, calc(100vw - 48px));
          overflow: hidden;
          box-shadow: 0 8px 32px rgba(0,0,0,0.12);
        "
      >
        <div
