const MAX_EVENTS = 100;

export type LlmDebugEvent = {
  ts: number;
  kind: "request" | "response";
  method: string;
  host: string;
  path: string;
  status?: number;
  contentType?: string;
  body: unknown;
  flowId: string;
};

const buffer: LlmDebugEvent[] = [];

const LLM_PATH_PATTERNS = [
  "/v1/chat/completions",
  "/v1/completions",
  "/v1/responses",
  "/v1/messages",
  "/openai-compatible/",
];

function isLlmRequest(url: string): boolean {
  return LLM_PATH_PATTERNS.some((p) => url.includes(p));
}

let installed = false;
let originalFetch: typeof globalThis.fetch | null = null;

export function installLlmFetchInterceptor(): void {
  if (installed) return;
  installed = true;
  originalFetch = globalThis.fetch;
  console.error("[llm-debug] installLlmFetchInterceptor");

  globalThis.fetch = (async (input: RequestInfo | URL, init?: RequestInit) => {
    const url = typeof input === "string"
      ? input
      : input instanceof URL
        ? input.toString()
        : input instanceof Request
          ? input.url
          : "";

    if (!url || !isLlmRequest(url)) {
      return originalFetch!(input, init);
    }

    const parsedUrl = new URL(url);
    const flowId = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const method = init?.method ?? (input instanceof Request ? input.method : "POST");

    // Capture request body
    try {
      const rawBody = init?.body;
      let bodyText: string | undefined;
      if (typeof rawBody === "string") {
        bodyText = rawBody;
      } else if (Buffer.isBuffer(rawBody)) {
        bodyText = rawBody.toString("utf8");
      }
      if (bodyText) {
        let parsedBody: unknown = bodyText;
        try { parsedBody = JSON.parse(bodyText); } catch {}
        recordLlmDebugEvent({
          ts: Date.now(),
          kind: "request",
          method,
          host: parsedUrl.host,
          path: `${parsedUrl.pathname}${parsedUrl.search}`,
          contentType: init?.headers instanceof Headers
            ? (init.headers.get("content-type") ?? undefined)
            : undefined,
          body: parsedBody,
          flowId,
        });
      }
    } catch {}

    const response = await originalFetch!(input, init);

    // Capture response body (non-blocking)
    try {
      const cloned = response.clone();
      void cloned.text().then((respText) => {
        let parsedBody: unknown = respText;
        const ct = response.headers.get("content-type") ?? "";
        if (respText.trim().startsWith("{") || respText.trim().startsWith("[")) {
          try { parsedBody = JSON.parse(respText); } catch {}
        }
        recordLlmDebugEvent({
          ts: Date.now(),
          kind: "response",
          method,
          host: parsedUrl.host,
          path: `${parsedUrl.pathname}${parsedUrl.search}`,
          status: response.status,
          contentType: ct || undefined,
          body: parsedBody,
          flowId,
        });
      }).catch(() => {});
    } catch {}

    return response;
  }) as typeof globalThis.fetch;
}

export function recordLlmDebugEvent(event: LlmDebugEvent): void {
  buffer.push(event);
  if (buffer.length > MAX_EVENTS) {
    buffer.splice(0, buffer.length - MAX_EVENTS);
  }
}

export function getLlmDebugEvents(limit = 50): LlmDebugEvent[] {
  return buffer.slice(-limit).reverse();
}

export function clearLlmDebugEvents(): void {
  buffer.length = 0;
}

