export function buildGuardedModelFetch(model: Model<Api>, timeoutMs?: number): typeof fetch {
  const requestConfig = resolveModelRequestPolicy(model);
  const dispatcherPolicy = buildProviderRequestDispatcherPolicy(requestConfig);
  const requestTimeoutMs = resolveModelRequestTimeoutMs(model, timeoutMs);
  return async (input, init) => {
    console.error(`[llm-debug] buildGuardedModelFetch called, model=${model.id}`);
    const request = input instanceof Request ? new Request(input, init) : undefined;
    const url =
      request?.url ??
      (input instanceof URL
        ? input.toString()
        : typeof input === "string"
          ? input
          : (() => {
              throw new Error("Unsupported fetch input for transport-aware model request");
            })());
    const policy = resolveModelTransportSsrFPolicy({
      model,
      url,
      allowPrivateNetwork: requestConfig.allowPrivateNetwork,
    });
    const requestInit =
      request &&
      ({
        method: request.method,
        headers: request.headers,
        body: request.body ?? undefined,
        redirect: request.redirect,
        signal: request.signal,
        ...(request.body ? ({ duplex: "half" } as const) : {}),
      } satisfies RequestInit & { duplex?: "half" });
    const guardedFetchOptions = {
      url,
      init: requestInit ?? init,
      capture: {
        meta: {
          provider: model.provider,
          api: model.api,
          model: model.id,
        },
      },
      dispatcherPolicy,
      timeoutMs: requestTimeoutMs,
      // Provider transport intentionally keeps the secure default and never
      // replays unsafe request bodies across cross-origin redirects.
      allowCrossOriginUnsafeRedirectReplay: false,
      ...(policy ? { policy } : {}),
    };

    // Capture request body for debug
    const flowId = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    try {
      const parsedUrl = new URL(url);
      const rawBody = init?.body ?? requestInit?.body;
      console.error(`[llm-debug] rawBody type=${typeof rawBody} isBuffer=${Buffer.isBuffer(rawBody)} isStream=${rawBody instanceof ReadableStream} initKeys=${init ? Object.keys(init).join(",") : "undefined"}`);
      let requestBodyText: string | undefined;
      if (typeof rawBody === "string") {
        requestBodyText = rawBody;
      } else if (Buffer.isBuffer(rawBody)) {
        requestBodyText = rawBody.toString("utf8");
      }
      if (requestBodyText) {
        let parsedBody: unknown = requestBodyText;
        try {
          parsedBody = JSON.parse(requestBodyText);
        } catch {}
        const reqHeaders = init?.headers ?? requestInit?.headers;
        recordLlmDebugEvent({
          ts: Date.now(),
          kind: "request",
          method: init?.method ?? requestInit?.method ?? "POST",
          host: parsedUrl.host,
          path: `${parsedUrl.pathname}${parsedUrl.search}`,
          contentType: reqHeaders instanceof Headers
            ? (reqHeaders.get("content-type") ?? undefined)
            : undefined,
          body: parsedBody,
          flowId,
        });
      }
    } catch {}

    const result = await fetchWithSsrFGuard(
      !dispatcherPolicy && shouldUseEnvHttpProxyForUrl(url)
        ? withTrustedEnvProxyGuardedFetchMode(guardedFetchOptions)
        : guardedFetchOptions,
    );
    let response = result.response;
    if (shouldBypassLongSdkRetry(response)) {
      const headers = new Headers(response.headers);
      headers.set("x-should-retry", "false");
      response = new Response(response.body, {
        status: response.status,
        statusText: response.statusText,
        headers,
      });
    }

    // Capture response body for debug (non-blocking)
    try {
      const parsedUrl = new URL(url);
      const cloned = response.clone();
      void cloned.text().then((respText) => {
        let parsedBody: unknown = respText;
        const ct = response.headers.get("content-type") ?? "";
        if (respText.trim().startsWith("{") || respText.trim().startsWith("[")) {
          try {
            parsedBody = JSON.parse(respText);
          } catch {}
        } else if (ct.includes("event-stream") || respText.trim().startsWith("data:")) {
          parsedBody = respText;
        }
        recordLlmDebugEvent({
          ts: Date.now(),
          kind: "response",
          method: init?.method ?? requestInit?.method ?? "POST",
          host: parsedUrl.host,
          path: `${parsedUrl.pathname}${parsedUrl.search}`,
