import { html, nothing } from "lit";
import { unsafeHTML } from "lit/directives/unsafe-html.js";
import type { GatewayBrowserClient } from "../gateway.ts";

export type DebugFrame = { direction: "out" | "in"; ts: number; data: unknown };

export type DebugModalState = {
  open: boolean;
  loading: boolean;
  events: unknown[];
  error: string | null;
};

type CaptureEvent = {
  kind?: string;
  direction?: string;
  method?: string;
  host?: string;
  path?: string;
  status?: number;
  contentType?: string;
  body?: unknown;
  flowId?: string;
};

export async function loadDebugCaptureEvents(
  client: GatewayBrowserClient | null,
  debugSessionId?: string,
): Promise<{
  events: unknown[];
  error: string | null;
}> {
  if (!client) {
    return { events: [], error: "Gateway not connected" };
  }
  try {
    const result = (await client.request("debug.capture.recent", {
      limit: 100,
      ...(debugSessionId ? { debugSessionId } : {}),
    })) as {
      enabled: boolean;
      events?: unknown[];
    };
    if (!result.enabled) {
      return { events: [], error: "Debug proxy not enabled. Set OPENCLAW_DEBUG_PROXY_ENABLED=1" };
    }
    return { events: result.events ?? [], error: null };
  } catch (err) {
    return { events: [], error: err instanceof Error ? err.message : String(err) };
  }

