import { html, nothing, type TemplateResult } from "lit";
import type { GatewayBrowserClient } from "../gateway.ts";

export type DebugFrame = { direction: "out" | "in"; ts: number; data: unknown };

type CaptureEvent = {
  kind?: string;
  direction?: string;
  method?: string;
  host?: string;
  path?: string;
  status?: number;
  contentType?: string;
  body?: unknown;
  flowId?: string;
};

export async function loadDebugCaptureEvents(
  client: GatewayBrowserClient | null,
  debugSessionId?: string,
): Promise<{ events: unknown[]; error: string | null }> {
  if (!client) return { events: [], error: "Gateway not connected" };
  try {
    const result = (await client.request("debug.capture.recent", {
      limit: 100,
      ...(debugSessionId ? { debugSessionId } : {}),
    })) as { enabled: boolean; events?: unknown[] };
    if (!result.enabled) return { events: [], error: "Debug proxy not enabled" };
    return { events: result.events ?? [], error: null };
  } catch (err) {
    return { events: [], error: err instanceof Error ? err.message : String(err) };
  }
}

// Recursive JSON tree renderer with collapsible nodes
function renderJsonValue(value: unknown, key?: string, depth = 0): TemplateResult {
  if (value === null) {
    return html`<span style="color: #757575; font-style: italic;">null</span>`;
  }
  if (typeof value === "boolean") {
    return html`<span style="color: #6a1b9a;">${value}</span>`;
  }
  if (typeof value === "number") {
    return html`<span style="color: #1565c0;">${value}</span>`;
  }
  if (typeof value === "string") {
    // Render newlines as <br> for readability
    const hasNewlines = value.includes("\n");
    if (hasNewlines) {
      const lines = value.split("\n");
      return html`<span style="color: #2e7d32;">"<span style="white-space: pre-wrap;">${lines.map((line, i) => i > 0 ? html`<br />\n${line}` : line)}</span>"</span>`;
    }
    return html`<span style="color: #2e7d32;">"${value}"</span>`;
  }
  if (Array.isArray(value) || (typeof value === "object" && value !== null)) {
    return renderCollapsibleNode(value, key, depth);
  }
  return html`<span>${String(value)}</span>`;
}

function renderCollapsibleNode(value: unknown, key: string | undefined, depth: number): TemplateResult {
  const isArray = Array.isArray(value);
  const entries = isArray
    ? (value as unknown[]).map((v, i) => [String(i), v] as const)
    : Object.entries(value as Record<string, unknown>);
  const isEmpty = entries.length === 0;
  const openByDefault = depth < 1;
  const summary = isArray ? `[${entries.length}]` : `{${entries.length}}`;

  if (isEmpty) {
    return html`
      <span style="color: #666;">${key !== undefined ? html`<span style="color: #c62828; font-weight: 600;">"${key}"</span>: ` : ""}${isArray ? "[]" : "{}"}</span>
    `;
  }

  return html`
    <details ?open=${openByDefault} style="display: inline;">
      <summary
        style="
          cursor: pointer;
          user-select: none;
          display: inline;
          list-style: none;
        "
      >
        ${key !== undefined
          ? html`<span style="color: #c62828; font-weight: 600;">"${key}"</span>: `
          : ""}
        <span style="color: #666; font-size: 11px;">${isArray ? "[" : "{"} ${entries.length} ${isArray ? "items" : "keys"} ${isArray ? "]" : "}"} ▸</span>
      </summary>
      <span style="color: #999; font-size: 11px;">${isArray ? "[" : "{"}</span>
