    <openclaw-modal-dialog label="Debug - LLM Raw Payloads" @modal-cancel=${params.onClose}>
      <div style="background: #ffffff; color: #1a1a1a; border: 1px solid #e0e0e0; border-radius: 12px; display: flex; flex-direction: column; max-height: calc(100dvh - 96px); width: min(900px, calc(100vw - 48px)); overflow: hidden; box-shadow: 0 8px 32px rgba(0,0,0,0.12);">
        <div style="display: flex; align-items: center; justify-content: flex-end; padding: 8px 16px; border-bottom: 1px solid #e0e0e0;">
          <button class="btn btn--sm" @click=${params.onClose} style="font-size: 12px;">Close</button>
        </div>
        <div style="overflow: auto; padding: 12px 16px; flex: 1; background: #f5f5f5;">
          ${params.captureLoading
