              : events.length === 0
                ? html`<p style="margin: 0; color: #666;">No LLM request body captured. Send a message first.</p>`
                : events.map((event, i) => renderEventCard(event, i))}
        </div>
      </div>
    </openclaw-modal-dialog>
  `;
}

